const incoming = $input.all();
let products = [];

for (const item of incoming) {
  const j = item.json;
  if (Array.isArray(j)) {
    products.push(...j);
  } else if (Array.isArray(j?.data)) {
    products.push(...j.data);
  } else if (j && typeof j === 'object') {
    products.push(j);
  }
}

const now = new Date();
const fetchedAt = now.toISOString();
const runDate = fetchedAt.slice(0, 10);
const runId = `quickmart_${fetchedAt.replace(/[:.]/g, '-')}`;

return products
  .filter(p => p && p.id !== undefined)
  .map(p => ({
    json: {
      product_id: Number(p.id),
      title: String(p.title ?? ''),
      price: Number(p.price ?? 0),
      category: String(p.category ?? 'unknown'),
      description: String(p.description ?? ''),
      rating_rate: Number(p.rating?.rate ?? 0),
      rating_count: Number(p.rating?.count ?? 0),
      fetched_at: fetchedAt,
      run_id: runId,
      run_date: runDate
    }
  }));

const apiProducts = $('Normalize API Products').all().map(i => i.json);
const existingRows = $input.all()
  .map(i => i.json)
  .filter(r => r && r.product_id !== undefined && r.product_id !== null);

const existingKeys = new Set(
  existingRows.map(r => `${Number(r.product_id)}|${String(r.run_date).slice(0,10)}`)
);

const fresh = apiProducts.filter(p => {
  const key = `${Number(p.product_id)}|${String(p.run_date).slice(0,10)}`;
  return !existingKeys.has(key);
});

if (fresh.length === 0) {
  return [{
    json: {
      _no_new: true,
      run_id: apiProducts[0]?.run_id || '',
      run_date: apiProducts[0]?.run_date || new Date().toISOString().slice(0,10),
      skipped_duplicates: apiProducts.length
    }
  }];
}

return fresh.map(p => ({
  json: {
    ...p,
    _no_new: false,
    skipped_duplicates: apiProducts.length - fresh.length
  }
}));

const rows = $input.all()
  .map(i => i.json)
  .filter(r => r && r.product_id !== undefined && r.product_id !== null);

if (rows.length === 0) {
  return [{
    json: {
      error: true,
      summary_text: 'QuickMart analysis could not run because no stored product rows were returned from Supabase.'
    }
  }];
}

const threshold = Number($('CONFIG - Settings').first().json.high_value_threshold ?? 50);
const currentRunId = $('Normalize API Products').first().json.run_id;
const currentRunDate = $('Normalize API Products').first().json.run_date;

const dateGroups = {};
for (const r of rows) {
  const d = String(r.run_date || r.fetched_at || '').slice(0, 10);
  if (!dateGroups[d]) dateGroups[d] = [];
  dateGroups[d].push(r);
}

const dates = Object.keys(dateGroups).filter(Boolean).sort();
const latestDate = dates[dates.length - 1];
const previousDate = dates.length > 1 ? dates[dates.length - 2] : null;
const latest = dateGroups[latestDate] || [];
const previous = previousDate ? (dateGroups[previousDate] || []) : [];

const highValue = latest.filter(r => Number(r.price) > threshold);
const averagePrice = latest.length
  ? latest.reduce((s, r) => s + Number(r.price || 0), 0) / latest.length
  : 0;
const ratingRows = latest.filter(r => Number.isFinite(Number(r.rating_rate)));
const averageRating = ratingRows.length
  ? ratingRows.reduce((s, r) => s + Number(r.rating_rate || 0), 0) / ratingRows.length
  : 0;

const categories = {};
for (const r of latest) {
  const c = String(r.category || 'unknown');
  categories[c] = (categories[c] || 0) + 1;
}

const electronicsCount = latest.filter(
  r => String(r.category || '').toLowerCase() === 'electronics'
).length;

const newRecordsThisExecution = rows.filter(r => String(r.run_id) === String(currentRunId)).length;
const examples = highValue.slice(0, 2).map(r => r.title);
const productCountChange = previousDate ? latest.length - previous.length : null;

const categoryText = Object.entries(categories)
  .sort((a,b) => b[1]-a[1])
  .map(([k,v]) => `${k}: ${v}`)
  .join(', ');

const historyText = previousDate
  ? `${previousDate}: ${previous.length} products → ${latestDate}: ${latest.length} products (change ${productCountChange >= 0 ? '+' : ''}${productCountChange})`
  : `First stored snapshot: ${latestDate} (${latest.length} products)`;

const summaryText =
`📊 QuickMart Daily Product Analysis
Snapshot date: ${latestDate}
Total products in latest snapshot: ${latest.length}
Historical rows stored: ${rows.length}
New rows inserted this execution: ${newRecordsThisExecution}
Products above $${threshold}: ${highValue.length}
Average price: $${averagePrice.toFixed(2)}
Average rating: ${averageRating.toFixed(2)}
Electronics products: ${electronicsCount}
Products by category: ${categoryText}
High-value examples: ${examples.length ? examples.join(' | ') : 'None'}
Historical comparison: ${historyText}`;

return [{
  json: {
    error: false,
    timestamp: new Date().toISOString(),
    current_run_id: currentRunId,
    current_run_date: currentRunDate,
    snapshot_date: latestDate,
    total_products: latest.length,
    historical_records: rows.length,
    new_records_this_execution: newRecordsThisExecution,
    high_value_threshold: threshold,
    high_value_products: highValue.length,
    high_value_examples: examples.join(' | '),
    average_price: Number(averagePrice.toFixed(2)),
    average_rating: Number(averageRating.toFixed(2)),
    electronics_count: electronicsCount,
    category_breakdown: categoryText,
    previous_snapshot_date: previousDate || '',
    previous_snapshot_products: previousDate ? previous.length : 0,
    product_count_change: productCountChange ?? 0,
    summary_text: summaryText
  }
}];

const j = $json;
return [{
  json: {
    timestamp: j.timestamp,
    snapshot_date: j.snapshot_date,
    total_products: j.total_products,
    historical_records: j.historical_records,
    new_records_this_execution: j.new_records_this_execution,
    high_value_products: j.high_value_products,
    average_price: j.average_price,
    average_rating: j.average_rating,
    electronics_count: j.electronics_count,
    category_breakdown: j.category_breakdown,
    previous_snapshot_date: j.previous_snapshot_date,
    previous_snapshot_products: j.previous_snapshot_products,
    product_count_change: j.product_count_change
  }
}];
